+				} else {
+					EditorNode::get_singleton()->add_io_error(TTR("Unable to update dependencies for:") + "\n" + file_path + "\n");
+				}
+			}
+			if (need_update_modified_time) {
+				fi->modified_time = FileAccess::get_modified_time(file_path);
+			}
+		}
+	}
